'use strict';
const agentLaunch=document.createElement('button');agentLaunch.className='secondary agent-launch';agentLaunch.id='ask-revolve';agentLaunch.textContent='✧ Ask ReVolve';document.querySelector('.header-right').prepend(agentLaunch);
const agentDialog=document.createElement('dialog');agentDialog.className='agent-dialog';agentDialog.setAttribute('aria-labelledby','agent-title');agentDialog.innerHTML=`<div class="agent-top"><div><span class="eyebrow">SAMPLE-DATA ASSISTANT</span><h2 id="agent-title">Ask ReVolve</h2></div><button class="close" id="agent-close" aria-label="Close AI assistant">×</button></div><p class="agent-scope">Read-only access to the built-in sample register. Browser edits and new travelers are not included. No live HPE connection.</p><div id="agent-connection" role="status">Checking connection…</div><div class="agent-suggestions"><button data-question="Which sample returns are blocked, and who owns the issues?">Find blocked returns</button><button data-question="Explain how a return moves from receiving to closure.">Explain the workflow</button><button id="ask-current">Explain this return</button></div><div id="agent-chat" role="log" aria-label="Agent conversation" aria-live="polite"></div><form id="agent-form"><label for="agent-question">Ask about the sample workflow</label><div class="agent-compose"><textarea id="agent-question" maxlength="1200" rows="2" required placeholder="Why is RV-1048 blocked?"></textarea><button class="primary" id="agent-send">Ask →</button></div><p>OpenAI-powered · Recommendations require human review · Do not enter real business or personal data.</p></form>`;document.body.append(agentDialog);
let agentHistory=[],agentBusy=false,agentContext=null,agentReturnFocus=null;
function agentMessage(role,content,sources=[]){const el=document.createElement('div');el.className='agent-message '+role;const label=document.createElement('strong');label.textContent=role==='user'?'You':'ReVolve';const text=document.createElement('div');text.textContent=content;el.append(label,text);if(sources.length){const source=document.createElement('small');source.textContent='Read from: '+sources.join(' · ');el.append(source)}document.querySelector('#agent-chat').append(el);el.scrollIntoView({block:'nearest'});}
async function checkAgent(){try{const r=await fetch('/api/agent',{cache:'no-store'});if(!r.ok)throw new Error();const status=await r.json();document.querySelector('#agent-connection').textContent=status.configured?'Connected · fixed sample data · read only':'Awaiting setup · the site owner must add the API key in Vercel and redeploy.';}catch{document.querySelector('#agent-connection').textContent='AI endpoint unavailable in this preview. Use the deployed Vercel site.';}}
function openAgent(){if(agentDialog.open)return;agentReturnFocus=document.activeElement;agentContext=typeof selected!=='undefined'&&selected?selected:null;const currentButton=document.querySelector('#ask-current');currentButton.textContent=agentContext?'Explain '+agentContext:'Explain RV-1048';agentDialog.showModal();checkAgent();document.querySelector('#agent-question').focus();}
function closeAgent(){if(agentBusy)return;agentDialog.close();agentReturnFocus?.focus()}
agentLaunch.onclick=openAgent;document.querySelector('#agent-close').onclick=closeAgent;
agentDialog.addEventListener('cancel',e=>{e.preventDefault();closeAgent()});
// Keep the existing traveler focus trap from intercepting keyboard input in this modal.
agentDialog.addEventListener('keydown',e=>e.stopPropagation());
document.querySelectorAll('[data-question]').forEach(b=>b.onclick=()=>{document.querySelector('#agent-question').value=b.dataset.question;document.querySelector('#agent-question').focus()});
document.querySelector('#ask-current').onclick=()=>{document.querySelector('#agent-question').value='Summarize '+(agentContext||'RV-1048')+', explain its holds and allowed next actions.';document.querySelector('#agent-question').focus()};
document.querySelector('#agent-form').onsubmit=async e=>{
 e.preventDefault();if(agentBusy)return;const box=document.querySelector('#agent-question'),question=box.value.trim();if(!question)return;
 agentBusy=true;document.querySelector('#agent-send').disabled=true;document.querySelector('#agent-close').disabled=true;document.querySelector('#agent-send').textContent='Reading…';agentMessage('user',question);box.value='';
 try{const response=await fetch('/api/agent',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question,returnId:agentContext,history:agentHistory.slice(-4)}),signal:AbortSignal.timeout(80000)});let data;try{data=await response.json()}catch{throw new Error('The AI endpoint did not return a response. Please try again.')}if(!response.ok)throw new Error(data.error||'Unable to answer right now.');agentMessage('assistant',data.answer,data.sources||[]);agentHistory.push({role:'user',content:question},{role:'assistant',content:data.answer});agentHistory=agentHistory.slice(-4);document.querySelector('#agent-connection').textContent='Connected · fixed sample data · read only';}
 catch(error){agentMessage('assistant',error.name==='TimeoutError'?'The request took too long. Please try a shorter question.':error.message);}
 finally{agentBusy=false;document.querySelector('#agent-send').disabled=false;document.querySelector('#agent-close').disabled=false;document.querySelector('#agent-send').textContent='Ask →';box.focus();}
};
const originalAgentDraw=drawRecord;drawRecord=function(){originalAgentDraw();const actions=document.createElement('button');actions.className='secondary';actions.style.marginTop='18px';actions.textContent='✧ Ask AI about this sample return';actions.onclick=openAgent;document.querySelector('#drawer').append(actions)};
